//! Tracing utilities for observing PTIR program capture and execution.
//!
//! The tracing layer exposes lightweight hooks so callers can inspect the PTIR programs
//! generated by lazy graphs. Consumers install a global [`ExecutionTraceSink`], which receives
//! callbacks before and after each backend execution and an event after each pass of the pipeline.

use std::fmt;
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::{Arc, Mutex, RwLock};
use std::time::{Duration, SystemTime};

use gpt_rs_ir::ir::Module;
use gpt_rs_ir::passes::{self, Pipeline};
use gpt_rs_ir::text::TextOptions;
use serde::Serialize;

use crate::ops::graph::ValueId;

/// Dumped programs are stored programs, with the location and the number of each op.
const DUMPED_TEXT: TextOptions = TextOptions {
    versioned: true,
    locations: true,
    numbers: true,
};

/// Describes the kind of PTIR program being executed.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "kind", content = "payload")]
pub enum ProgramKind {
    /// Program generated to materialize a specific value identifier.
    Materialize { values: Vec<ValueId> },
    /// Program generated during explicit flushing (e.g., full-graph execution).
    FlushAll,
    /// Custom tag supplied by higher-level callers.
    Custom { label: String },
    /// The program of a traced function, run again on new inputs without recording.
    Replay,
}

impl ProgramKind {
    pub fn label(&self) -> &str {
        match self {
            ProgramKind::Materialize { .. } => "materialize",
            ProgramKind::FlushAll => "flush_all",
            ProgramKind::Custom { label } => label.as_str(),
            ProgramKind::Replay => "replay",
        }
    }
}

impl fmt::Display for ProgramKind {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            ProgramKind::Materialize { values } => {
                if let Some(first) = values.first() {
                    write!(f, "materialize_%{}", first.0)
                } else {
                    write!(f, "materialize")
                }
            }
            ProgramKind::FlushAll => write!(f, "flush_all"),
            ProgramKind::Custom { label } => write!(f, "{label}"),
            ProgramKind::Replay => write!(f, "replay"),
        }
    }
}

/// Metadata provided alongside each PTIR execution.
#[derive(Debug, Clone, Serialize)]
pub struct ProgramContext {
    pub trace_id: u64,
    pub graph_id: usize,
    pub backend: String,
    /// The plan key: equal for two programs exactly when one can run in place of the other.
    pub plan_hash: u64,
    /// True when the program came from the program cache, so the pass pipeline did not run.
    pub program_cache_hit: bool,
    pub targets: Vec<ValueId>,
    pub outputs: Vec<ValueId>,
    pub exports: Vec<ValueId>,
    pub timestamp: SystemTime,
    pub kind: ProgramKind,
}

/// Status reported after executing a PTIR program.
#[derive(Debug, Clone, Serialize)]
#[serde(tag = "status", content = "details")]
pub enum ProgramStatus {
    Success,
    Failure { message: String },
}

/// Summary emitted once a PTIR program finishes (or fails).
#[derive(Debug, Clone, Serialize)]
pub struct ProgramStats {
    pub duration: Duration,
    pub output_count: usize,
    pub status: ProgramStatus,
}

/// Receives callbacks around PTIR program execution and pass activity. The callbacks run on the
/// thread that runs the program or the pass.
pub trait ExecutionTraceSink: Send + Sync {
    /// Called before a program runs, with the module it was compiled from.
    fn before_program(&self, context: &ProgramContext, module: &Module);
    fn after_program(&self, context: &ProgramContext, stats: &ProgramStats);

    /// Called after each pass of the pipeline, with the module after it.
    fn on_pass(&self, _pass: &PassRun, _module: &Module) {}

    /// Called with a file a backend made from a module, such as the source it generated, named
    /// `name`, after the passes that made the module.
    fn on_artifact(&self, _name: &str, _contents: &str) {}
}

/// Runs the passes of `pipeline` on `module`, verifying after each, in a profiler scope each. A
/// trace sink receives the module after each pass.
pub fn run_pipeline(module: &mut Module, pipeline: &Pipeline) -> anyhow::Result<()> {
    let installed = current_sink();
    for pass in pipeline.passes() {
        let _scope = crate::profiling::compile_pass_scope(pass.name());
        let changed = passes::run_pass(pass.as_ref(), module)?;
        let stats = passes::take_stats();
        if let Some(sink) = &installed {
            let run = PassRun {
                name: pass.name(),
                options: &pass.options(),
                changed,
                stats: &stats,
            };
            sink.on_pass(&run, module);
        }
    }
    Ok(())
}

/// Hands the trace sink, if one is installed, the file `contents` named `name`.
pub fn artifact(name: &str, contents: &str) {
    if let Some(sink) = current_sink() {
        sink.on_artifact(name, contents);
    }
}

/// What one pass of the pipeline did.
pub struct PassRun<'a> {
    pub name: &'static str,
    /// The options that differ from their defaults, as `{name = value, ...}`, or empty.
    pub options: &'a str,
    pub changed: bool,
    /// The pass's statistics, in the order it first counted them.
    pub stats: &'a [(&'static str, u64)],
}

static GLOBAL_TRACE_SINK: RwLock<Option<Arc<dyn ExecutionTraceSink>>> = RwLock::new(None);
/// Whether a sink is installed, so that [`current_sink`] takes no lock when none is.
static SINK_INSTALLED: AtomicBool = AtomicBool::new(false);
static TRACE_ID_COUNTER: AtomicU64 = AtomicU64::new(0);

/// Guard returned when installing a trace sink. Restores the previous sink on drop.
pub struct TraceGuard {
    previous: Option<Arc<dyn ExecutionTraceSink>>,
    active: bool,
}

impl Drop for TraceGuard {
    fn drop(&mut self) {
        if self.active {
            let mut lock = GLOBAL_TRACE_SINK
                .write()
                .unwrap_or_else(|poisoned| poisoned.into_inner());
            *lock = self.previous.take();
            SINK_INSTALLED.store(lock.is_some(), Ordering::Release);
            self.active = false;
        }
    }
}

/// Installs a global execution trace sink, returning a guard that restores the previous sink.
pub fn install_global_sink(sink: Arc<dyn ExecutionTraceSink>) -> TraceGuard {
    let mut lock = GLOBAL_TRACE_SINK
        .write()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let previous = lock.clone();
    *lock = Some(sink);
    SINK_INSTALLED.store(true, Ordering::Release);
    TraceGuard {
        previous,
        active: true,
    }
}

/// Whether a global sink is installed, so recording keeps the locations of ops for it.
pub fn sink_installed() -> bool {
    SINK_INSTALLED.load(Ordering::Acquire)
}

/// Returns the currently installed global sink, if any.
pub fn current_sink() -> Option<Arc<dyn ExecutionTraceSink>> {
    if !sink_installed() {
        return None;
    }
    GLOBAL_TRACE_SINK
        .read()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .clone()
}

/// Allocates a fresh trace identifier for program execution.
pub fn next_trace_id() -> u64 {
    TRACE_ID_COUNTER.fetch_add(1, Ordering::Relaxed)
}

/// Configuration flags for the [`FileTraceSink`].
#[derive(Debug, Clone)]
pub struct FileTraceOptions {
    pub emit_ptir: bool,
    pub emit_pass_events: bool,
    pub dump_filter: ProgramDumpFilter,
    pub emit_execution_log: bool,
}

impl Default for FileTraceOptions {
    fn default() -> Self {
        Self {
            emit_ptir: true,
            emit_pass_events: true,
            dump_filter: ProgramDumpFilter::AllExecutions,
            emit_execution_log: true,
        }
    }
}

/// Controls which program executions are materialized as per-run directories under a dump root.
#[derive(Debug, Clone, Copy)]
pub enum ProgramDumpFilter {
    /// Dump every backend program execution.
    AllExecutions,
    /// Dump only when a program is newly compiled (miss in the global program cache).
    ///
    /// All executions are still recorded in `executions.jsonl` when enabled.
    CompileOnly,
}

/// File-backed sink that stores PTIR programs and metadata on disk.
pub struct FileTraceSink {
    root: PathBuf,
    options: FileTraceOptions,
    sequence: AtomicU64,
    runs: Mutex<std::collections::HashMap<u64, RunRecord>>,
    pass_log: Mutex<Option<std::fs::File>>,
    execution_log: Mutex<Option<std::fs::File>>,
}

impl FileTraceSink {
    pub fn new(root: PathBuf) -> std::io::Result<Self> {
        std::fs::create_dir_all(&root)?;
        Ok(Self {
            root,
            options: FileTraceOptions::default(),
            sequence: AtomicU64::new(0),
            runs: Mutex::new(std::collections::HashMap::new()),
            pass_log: Mutex::new(None),
            execution_log: Mutex::new(None),
        })
    }

    pub fn with_options(root: PathBuf, options: FileTraceOptions) -> std::io::Result<Self> {
        std::fs::create_dir_all(&root)?;
        Ok(Self {
            root,
            options,
            sequence: AtomicU64::new(0),
            runs: Mutex::new(std::collections::HashMap::new()),
            pass_log: Mutex::new(None),
            execution_log: Mutex::new(None),
        })
    }

    fn reserve_dir(&self, context: &ProgramContext) -> std::io::Result<PathBuf> {
        let idx = self.sequence.fetch_add(1, Ordering::Relaxed);
        let dir_name = format!("{idx:05}_{}", context.kind);
        let path = self.root.join(dir_name);
        std::fs::create_dir_all(&path)?;
        Ok(path)
    }

    fn should_dump_execution(&self, context: &ProgramContext) -> bool {
        match self.options.dump_filter {
            ProgramDumpFilter::AllExecutions => true,
            ProgramDumpFilter::CompileOnly => !context.program_cache_hit,
        }
    }

    fn append_execution_record(&self, record: &ExecutionRecord) {
        if !self.options.emit_execution_log {
            return;
        }
        if let Ok(mut file_guard) = self.execution_log.lock() {
            if file_guard.is_none() {
                let path = self.root.join("executions.jsonl");
                if let Ok(file) = std::fs::OpenOptions::new()
                    .create(true)
                    .append(true)
                    .open(path)
                {
                    *file_guard = Some(file);
                }
            }
            if let Some(file) = file_guard.as_mut() {
                if let Ok(json) = serde_json::to_string(record) {
                    let _ = writeln!(file, "{json}");
                }
            }
        }
    }
}

#[derive(Debug)]
struct RunRecord {
    dir: Option<PathBuf>,
    dumped: bool,
    buffered_ptir: Option<String>,
}

#[derive(Serialize)]
struct ExecutionRecord<'a> {
    context: &'a ProgramContext,
    stats: &'a ProgramStats,
    dumped: bool,
}

impl ExecutionTraceSink for FileTraceSink {
    fn before_program(&self, context: &ProgramContext, module: &Module) {
        let should_dump = self.should_dump_execution(context);
        let ir = || module.print(DUMPED_TEXT);
        let mut record = RunRecord {
            dir: None,
            dumped: false,
            buffered_ptir: None,
        };

        if should_dump {
            if let Ok(dir) = self.reserve_dir(context) {
                if self.options.emit_ptir {
                    let _ = std::fs::write(dir.join("program.ptir"), ir());
                }
                if let Ok(meta) = serde_json::to_string_pretty(&context) {
                    let _ = std::fs::write(dir.join("meta.json"), meta);
                }
                record.dir = Some(dir);
                record.dumped = true;
            }
        } else if self.options.emit_ptir {
            // Buffer the program so a failure can still be materialized as an on-disk dump.
            record.buffered_ptir = Some(ir());
        }

        if let Ok(mut runs) = self.runs.lock() {
            runs.insert(context.trace_id, record);
        }
    }

    fn after_program(&self, context: &ProgramContext, stats: &ProgramStats) {
        let removed = if let Ok(mut runs) = self.runs.lock() {
            runs.remove(&context.trace_id)
        } else {
            None
        };

        let dumped = removed.as_ref().is_some_and(|record| record.dumped);

        if let Some(record) = removed {
            if let Some(dir) = record.dir {
                if let Ok(json) = serde_json::to_string_pretty(stats) {
                    let _ = std::fs::write(dir.join("stats.json"), json);
                }
            } else if matches!(stats.status, ProgramStatus::Failure { .. }) {
                // Materialize a dump directory on failure, even in CompileOnly mode.
                if let Ok(dir) = self.reserve_dir(context) {
                    if let Some(ptir) = record.buffered_ptir {
                        let _ = std::fs::write(dir.join("program.ptir"), ptir);
                    }
                    if let Ok(meta) = serde_json::to_string_pretty(&context) {
                        let _ = std::fs::write(dir.join("meta.json"), meta);
                    }
                    if let Ok(json) = serde_json::to_string_pretty(stats) {
                        let _ = std::fs::write(dir.join("stats.json"), json);
                    }
                }
            }
        }

        self.append_execution_record(&ExecutionRecord {
            context,
            stats,
            dumped,
        });
    }

    /// Writes the module after each pass to `passes/`. With `GPTRS_PASS_STATS`, it also logs
    /// the pass, its options, whether it changed the module, how many ops the module has and the
    /// pass's statistics to `passes.jsonl`.
    fn on_pass(&self, run: &PassRun, module: &Module) {
        if !self.options.emit_pass_events {
            return;
        }
        let pass = run.name;
        if crate::env::pass_stats_enabled() {
            self.append_pass_stats(&PassStats {
                pass,
                options: run.options,
                changed: run.changed,
                ops: module.walk(module.body()).len(),
                stats: run.stats.iter().copied().collect(),
            });
        }
        let pass_dir = self.root.join("passes");
        let _ = std::fs::create_dir_all(&pass_dir);
        let idx = self.sequence.fetch_add(1, Ordering::Relaxed);
        let file_name = format!("{idx:05}_{}.ptir", sanitize_file_fragment(pass));
        let _ = std::fs::write(pass_dir.join(file_name), module.print(DUMPED_TEXT));
    }

    /// Writes the file to `passes/`, after the dumps of the passes that made its module.
    fn on_artifact(&self, name: &str, contents: &str) {
        if !self.options.emit_pass_events {
            return;
        }
        let pass_dir = self.root.join("passes");
        let _ = std::fs::create_dir_all(&pass_dir);
        let idx = self.sequence.fetch_add(1, Ordering::Relaxed);
        let (stem, extension) = name.rsplit_once('.').unwrap_or((name, "txt"));
        let file_name = format!(
            "{idx:05}_{}.{}",
            sanitize_file_fragment(stem),
            sanitize_file_fragment(extension)
        );
        let _ = std::fs::write(pass_dir.join(file_name), contents);
    }
}

/// What one pipeline pass did: its options, whether it changed the module, how many ops the
/// module has after it, and the pass's statistics.
#[derive(Serialize)]
struct PassStats<'a> {
    pass: &'a str,
    #[serde(skip_serializing_if = "str::is_empty")]
    options: &'a str,
    changed: bool,
    ops: usize,
    #[serde(flatten)]
    stats: std::collections::BTreeMap<&'static str, u64>,
}

impl FileTraceSink {
    fn append_pass_stats(&self, stats: &PassStats) {
        let Ok(mut file_guard) = self.pass_log.lock() else {
            return;
        };
        if file_guard.is_none() {
            let path = self.root.join("passes.jsonl");
            *file_guard = std::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(path)
                .ok();
        }
        if let (Some(file), Ok(json)) = (file_guard.as_mut(), serde_json::to_string(stats)) {
            let _ = writeln!(file, "{json}");
        }
    }
}

use std::io::Write;

fn sanitize_file_fragment(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for ch in input.chars() {
        if ch.is_ascii_alphanumeric() || ch == '_' || ch == '-' {
            out.push(ch);
        } else {
            out.push('_');
        }
    }
    if out.is_empty() {
        "unnamed".to_string()
    } else {
        out
    }
}
